def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    cells = {}
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                cells.setdefault(out[r][c], []).append((r,c))
    for color, pts in cells.items():
        for r,c in pts:
            for dr,dc in ((1,1),(1,-1)):
                if (r+dr,c+dc) not in pts:
                    continue
                nr,nc=r+2*dr,c+2*dc
                while 0 <= nr < h and 0 <= nc < w:
                    if out[nr][nc] not in (0,color):
                        break
                    out[nr][nc]=color
                    nr+=dr; nc+=dc
    return out

