def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = [[False]*w for _ in range(h)]
    comps=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==bg or seen[r][c]: continue
        q=[(r,c)]; seen[r][c]=True; cells=[]
        for y,x in q:
          cells.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
