        c0=min(x for y,x in cells); c1=max(x for y,x in cells)
        area=(r1-r0+1)*(c1-c0+1)
        if len(cells)>=4 and len(cells)/area>=0.65:
          comps.append((len(cells)/area,len(cells),color,r0,r1,c0,c1))
    # Larger supported components define the object rectangles; overwrite only same-color overlaps.
    for density,n,color,r0,r1,c0,c1 in sorted(comps,key=lambda z:(z[1],z[0]),reverse=True):
