            r0=min(y for y,x in comp); r1=max(y for y,x in comp)
            c0=min(x for y,x in comp); c1=max(x for y,x in comp)
            # Each nested rectangular band is a uniform color. Reverse the band colors.
            layers=[]
            depth=0
            while r0+depth <= r1-depth and c0+depth <= c1-depth:
                cells=[(y,x) for y,x in comp if min(y-r0,r1-y,x-c0,c1-x)==depth]
                if not cells: break
                colors={grid[y][x] for y,x in cells}
                if len(colors)!=1: break
                layers.append(next(iter(colors)))
